class Solution:
    def maxFrequencyScore(self, nums: list[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        def cost(left: int, right: int) -> int:
            mid = (left + right) // 2
            med = nums[mid]
            left_cost = med * (mid - left + 1) - (pref[mid + 1] - pref[left])
            right_cost = (pref[right + 1] - pref[mid + 1]) - med * (right - mid)
            return left_cost + right_cost

        ans = 0
        left = 0
        for right in range(n):
            while cost(left, right) > k:
                left += 1
            ans = max(ans, right - left + 1)
        return ans

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxFrequencyScore(std::vector<int>& nums, long long k) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        std::vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + nums[i];
        }
        auto getCost = [&](int left, int right) -> long long {
            int mid = (left + right) / 2;
            long long med = nums[mid];
            long long leftCost = med * (mid - left + 1) - (pref[mid + 1] - pref[left]);
            long long rightCost = (pref[right + 1] - pref[mid + 1]) - med * (right - mid);
            return leftCost + rightCost;
        };
        int ans = 0, left = 0;
        for (int right = 0; right < n; ++right) {
            while (getCost(left, right) > k) {
                ++left;
            }
            ans = std::max(ans, right - left + 1);
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int maxFrequencyScore(int[] nums, long k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }
        int ans = 0, left = 0;
        for (int right = 0; right < n; right++) {
            while (getCost(pref, nums, left, right) > k) {
                left++;
            }
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }

    private long getCost(long[] pref, int[] nums, int left, int right) {
        int mid = (left + right) / 2;
        long med = nums[mid];
        long leftCost = med * (mid - left + 1) - (pref[mid + 1] - pref[left]);
        long rightCost = (pref[right + 1] - pref[mid + 1]) - med * (right - mid);
        return leftCost + rightCost;
    }
}

